import{_ as r,o as n,c as t,ah as i}from"./chunks/framework.DDXs_i7t.js";const m=JSON.parse('{"title":"Pressemappe: Das Horten-Mysterium","description":"","frontmatter":{},"headers":[],"relativePath":"pressemappe.md","filePath":"pressemappe.md"}'),s={name:"pressemappe.md"};function a(o,e,l,u,h,d){return n(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="pressemappe-das-horten-mysterium" tabindex="-1">Pressemappe: Das Horten-Mysterium <a class="header-anchor" href="#pressemappe-das-horten-mysterium" aria-label="Permalink to &quot;Pressemappe: Das Horten-Mysterium&quot;">​</a></h1><p>Willkommen im offiziellen Pressebereich des Horten-Mysteriums. Hier finden Journalisten, Blogger und Forensiker alle notwendigen Informationen zur Mockumentary des Jahres.</p><h2 id="uber-das-projekt" tabindex="-1">Über das Projekt <a class="header-anchor" href="#uber-das-projekt" aria-label="Permalink to &quot;Über das Projekt&quot;">​</a></h2><p>„Das Horten-Mysterium“ ist eine vierteilige Mockumentary, die den Aufstieg und die Verflechtungen des Horten-Imperiums mit der österreichischen Politik (insbesondere der ÖVP) beleuchtet. Wir nutzen Gemini CLI zur forensischen Aufarbeitung von Daten, Chats und historischen Dokumenten.</p><h2 id="zentrale-themen" tabindex="-1">Zentrale Themen <a class="header-anchor" href="#zentrale-themen" aria-label="Permalink to &quot;Zentrale Themen&quot;">​</a></h2><ul><li><strong>Der Pointillismus des Geldes:</strong> Wie kleine Spenden ein großes Bild der Macht ergeben.</li><li><strong>Die Harte Prosa:</strong> Analyse politischer Interventionen und Postenschacher.</li><li><strong>Fallstudie Peršmanhof:</strong> Die Dokumentation von „strukturellem Antislowenismus“ und staatlicher Willkür als historisches Echo.</li><li><strong>Marktbereinigung:</strong> Der Übergang von der Ära Wöginger zur Ära Hattmannsdorfer.</li></ul><h2 id="aktuelle-schwerpunkte-der-recherche" tabindex="-1">Aktuelle Schwerpunkte der Recherche <a class="header-anchor" href="#aktuelle-schwerpunkte-der-recherche" aria-label="Permalink to &quot;Aktuelle Schwerpunkte der Recherche&quot;">​</a></h2><h3 id="die-hydra-am-persmanhof" tabindex="-1">Die Hydra am Peršmanhof <a class="header-anchor" href="#die-hydra-am-persmanhof" aria-label="Permalink to &quot;Die Hydra am Peršmanhof&quot;">​</a></h3><p>In Zusammenarbeit mit Betroffenen und Rechtsexperten dokumentiert „Das Horten-Mysterium“ die rechtswidrige Kriminalisierung von Gedenkkultur.</p><ul><li><strong>Der Befund:</strong> Das Landesverwaltungsgericht Kärnten bestätigte am 16. April 2026 die Rechtswidrigkeit massiver Polizeieinsätze an der Gedenkstätte Peršmanhof.</li><li><strong>Struktureller Antislowenismus:</strong> Wir beleuchten die Kontinuität der Repression gegen die slowenische Volksgruppe – von den SS-Massakern 1945 bis zur heutigen bürokratischen und polizeilichen Schikane unter dem Deckmantel von Naturschutzgesetzen.</li><li><strong>Systemischer Kontrast:</strong> Während Interventionen im Finanzamt (Fall Wöginger) als „Bürgernähe“ verharmlost werden, wird zivilgesellschaftliches Gedenken mit Hubschraubern und Staatsschutz-Einsätzen beantwortet.</li></ul><h2 id="pressekontakt-materialien" tabindex="-1">Pressekontakt &amp; Materialien <a class="header-anchor" href="#pressekontakt-materialien" aria-label="Permalink to &quot;Pressekontakt &amp; Materialien&quot;">​</a></h2><p>Für Interviewanfragen, Bildmaterial in hoher Auflösung oder exklusive Einblicke in die forensischen Daten kontaktieren Sie bitte die Projektleitung über die <a href="/mitmachen.html">Whistleblower Tip-Line</a>.</p><hr><h2 id="exklusiv-gastbeitrag-die-„kopfnuss-zum-woginger-ruckzug" tabindex="-1">Exklusiv-Gastbeitrag: Die „Kopfnuss“ zum Wöginger-Rückzug <a class="header-anchor" href="#exklusiv-gastbeitrag-die-„kopfnuss-zum-woginger-ruckzug" aria-label="Permalink to &quot;Exklusiv-Gastbeitrag: Die „Kopfnuss“ zum Wöginger-Rückzug&quot;">​</a></h2><p><em>Von unserem Gastautor: Florian Armin Nusser (Investigativ-zynisches Kollektiv)</em></p><h3 id="kopfnuss-2303-die-harte-prosa-des-verschwindens" tabindex="-1">Kopfnuss #2303: Die Harte Prosa des Verschwindens <a class="header-anchor" href="#kopfnuss-2303-die-harte-prosa-des-verschwindens" aria-label="Permalink to &quot;Kopfnuss #2303: Die Harte Prosa des Verschwindens&quot;">​</a></h3><p>Guten Abend, liebes Österreich. Oder wie man in der ÖVP-Zentrale sagt: „Gute Nacht, Anstand.“</p><p>Wir müssen reden. Über den Gustl. Unseren August Wöginger. Der Mann, der uns die „Harte Prosa“ lehrte, hat heute eine neue literarische Gattung erfunden: Die <strong>„Fiktion der Arbeitsüberlastung“</strong>.</p><p>Hier sind die Fakten, kurz eingeordnet:</p><ol><li><p><strong>Das Wunder von Linz:</strong> August Wöginger tritt als Vize-Parteichef in Oberösterreich zurück. Die Begründung? Er sei „mehr als ausgelastet“. Genau jetzt. Dass am <strong>21. April</strong> das Urteil im Prozess wegen Anstiftung zum Amtsmissbrauch am Landesgericht Linz ansteht und nur 72 Stunden später der Landesparteitag folgt, ist natürlich reiner Zufall. So wie es reiner Zufall ist, dass man beim Eurozero-Spielen immer dann aufs Klo muss, wenn die Rechnung kommt.</p></li><li><p><strong>Die Akte Hattmannsdorfer:</strong> Während der Gustl also seine „Überlastung“ pflegt, rückt Wolfgang Hattmannsdorfer nach. Der „politische Vollprofi“. Ein Mann, der so strategisch denkt, dass er wahrscheinlich schon seine eigene Heiligsprechung geplant hat, inklusive Sponsoring durch die WKO. Er ist das neue, glatte Gesicht. Ohne Anklagebank-Aroma. Vorerst.</p></li><li><p><strong>Die Harte Prosa der Realität:</strong> Wenn die ÖVP von „freiwilligem Rückzug“ spricht, ist das meistens die höfliche Umschreibung für „Wir haben das Fluchtfahrzeug bereits vollgetankt“. Wöginger behält seine Bundesfunktionen. Denn in der ÖVP ist ein Prozess wegen Amtsmissbrauchs kein Rücktrittsgrund, sondern eine Art berufsbegleitende Fortbildung.</p></li></ol><p><strong>Fazit:</strong> Herr Wöginger, Sie sagen, Sie sind ausgelastet? Wir auch. Und zwar mit Ihren Ausreden.</p><p>Gute Nacht. Und schauen Sie sich das genau an. Es ist ein Bild aus lauter kleinen Punkten. Wenn man weit genug weggeht, sieht es aus wie ein Rücktritt. Wenn man genau hinsieht, ist es nur Angst vor dem Richter.</p><hr><p style="font-size:0.8rem;color:#888;text-align:center;"> Dies ist ein satirisches Kunstprojekt. <a href="disclaimer">Satire-Disclaimer</a></p>',24)])])}const c=r(s,[["render",a]]);export{m as __pageData,c as default};
